import React from 'react';
import DatasetCard from './DatasetCard';

export default function DatasetTable({ datasets }) {
  return (
    <div className="bg-card-light dark:bg-card-dark border border-default rounded shadow-sm">
      {/* Header Row */}
      <div className="grid grid-cols-6 gap-4 px-4 py-3 border-b border-default text-xs font-medium text-textSecondary-light dark:text-textSecondary-dark uppercase tracking-wider">
        <div className="col-span-2">Name</div>
        <div className="text-center">Source</div>
        <div className="text-center">Last Updated</div>
        <div className="text-center">Variables</div>
        <div className="text-center">Actions</div>
      </div>

      {/* Dataset Rows */}
      {datasets.map((_, index) => (
        <DatasetCard key={index} index={index} />
      ))}
    </div>
  );
}
